const digits='٠١٢٣٤٥٦٧٨٩';
function n(v){return String(v||'').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/[٠-٩]/g,d=>String(digits.indexOf(d))).toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,'')}
function t(v){return new Set(String(v||'').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/[٠-٩]/g,d=>String(digits.indexOf(d))).toLowerCase().split(/[^a-z0-9\u0600-\u06ff]+/).filter(x=>x.length>1))}
function g(v){const s=n(v),o=new Set();if(s.length<3){if(s)o.add(s);return o}for(let i=0;i<=s.length-3;i++)o.add(s.slice(i,i+3));return o}
function d(a,b){const A=g(a),B=g(b);if(!A.size||!B.size)return 0;let x=0;for(const z of A)if(B.has(z))x++;return 2*x/(A.size+B.size)}
