function near(a,b){const A=n(a.q),B=n(b.q);if(!A||!B)return false;if(A===B)return true;const mn=Math.min(A.length,B.length),mx=Math.max(A.length,B.length);return (mn>=24&&mx/mn<1.3&&d(a.q,b.q)>=.92)||(mn>=28&&j(a.q,b.q)>=.86)}
